<script setup lang="ts">import{onUnmounted,ref}from'vue';import{countries}from'../data/countries';import{shuffle,shareText}from'../utils';import{sound,vibrate}from'../audio';import{useI18n,locale}from'../i18n';const{t}=useI18n(),phase=ref<'intro'|'countdown'|'play'|'reveal'|'end'>('intro'),country=ref(countries[0]),score=ref(0),passed=ref(0),totalTime=ref(60),roundTime=ref(8),count=ref(3),feedback=ref('');let timer=0,lastGesture=0,neutral=true,revealTimer=0
function next(){country.value=shuffle(countries.filter(c=>c.code!==country.value.code))[0];roundTime.value=8;feedback.value='';phase.value='play'}
function reveal(reason:'timeout'|'pass'){if(phase.value!=='play')return;phase.value='reveal';if(reason==='pass')passed.value++;sound.wrong();vibrate(50);clearTimeout(revealTimer);revealTimer=window.setTimeout(next,1400)}
function act(ok:boolean){if(phase.value!=='play'||Date.now()-lastGesture<850)return;lastGesture=Date.now();if(ok){score.value++;feedback.value=t.value('correct');sound.correct();vibrate(35);phase.value='reveal';revealTimer=window.setTimeout(next,650)}else reveal('pass')}
function orientation(e:DeviceOrientationEvent){const beta=e.beta??0;if(Math.abs(beta)<35)neutral=true;if(neutral&&beta>55){neutral=false;act(true)}else if(neutral&&beta<20){neutral=false;act(false)}}
async function start(){const D=DeviceOrientationEvent as typeof DeviceOrientationEvent&{requestPermission?:()=>Promise<string>};try{if(D.requestPermission)await D.requestPermission()}catch{};addEventListener('deviceorientation',orientation);clearInterval(timer);clearTimeout(revealTimer);score.value=0;passed.value=0;totalTime.value=60;roundTime.value=8;phase.value='countdown';count.value=3;const pre=window.setInterval(()=>{count.value--;sound.tick();if(!count.value){clearInterval(pre);next();timer=window.setInterval(()=>{totalTime.value--;if(phase.value==='play'){roundTime.value--;sound.countdown(roundTime.value);if(roundTime.value<=0)reveal('timeout')}if(totalTime.value<=0){clearInterval(timer);clearTimeout(revealTimer);phase.value='end'}},1000)}},700)}
onUnmounted(()=>{clearInterval(timer);clearTimeout(revealTimer);removeEventListener('deviceorientation',orientation)});async function share(){await shareText(`FLAG STREAK PARTY 📱🌍\n🔥 ${score.value} ${t.value('flags')} in 60 secondi!`)}</script>
<template><section class="screen forehead"><template v-if="phase==='intro'"><RouterLink to="/home" class="back">← {{t('home')}}</RouterLink><div class="phone">📱</div><h1>{{t('forehead')}}</h1><p>Solo bandiere · 8 secondi per indovinare</p><div class="instructions"><div>⬇️ <b>{{t('tiltDown')}}</b></div><div>⬆️ <b>{{t('tiltUp')}}</b></div></div><button class="primary" @click="start">{{t('start')}}</button></template><div v-else-if="phase==='countdown'" class="countdown">{{count||'GO!'}}</div><template v-else-if="phase==='play'||phase==='reveal'"><header class="game-head"><RouterLink to="/home" class="icon-btn home-btn" :aria-label="t('home')">⌂</RouterLink><strong>🔥 {{score}}</strong><b class="pill">{{roundTime}}s</b><strong>⏱ {{totalTime}}</strong></header><div class="round-progress"><span :style="{width:(roundTime/8*100)+'%'}"></span></div><div class="party-card"><img class="party-flag" :src="country.flagAsset" alt="Bandiera da indovinare"><div v-if="phase==='reveal'" class="country-reveal"><small>{{t('answerWas')}}</small><h1>{{country.names[locale].toUpperCase()}}</h1><b v-if="feedback">{{feedback}}</b></div></div><div class="touch-fallback"><button :disabled="phase!=='play'" @click="act(false)">⬆️ {{t('pass')}}</button><button :disabled="phase!=='play'" @click="act(true)">⬇️ {{t('correct')}}</button></div></template><div v-else class="result"><div class="burst">⏰</div><h1>{{t('timeUp')}}</h1><p>{{t('guessed')}}</p><strong class="huge">{{score}} {{t('flags')}}</strong><p>{{t('passed')}}: {{passed}}</p><button class="primary" @click="start">{{t('replay')}}</button><button @click="share">↗ {{t('share')}}</button><RouterLink to="/home" class="text-btn">⌂ {{t('home')}}</RouterLink></div></section></template>
